private static Settings? _inst;
private static readonly object _gate = new();

public static Settings Instance
{
    get
    {
        if (_inst == null)                 // 1: без замка
        {
            lock (_gate)
            {
                if (_inst == null)         // 2: под замком
                    _inst = Settings.Load();
            }
        }
        return _inst;
    }
}

